syntax:
Key concepts: Menu, struct, vector, strings, references, functions, CRUD, search, sort, validation, files

#include <iostream>
#include <string>
#include <iomanip>
#include <vector>
#include <algorithm>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <utility>
using namespace std;
struct Record { string id, name; double grade; };
void validateGrade(double grade) { if (!(grade >= 0 && grade <= 100)) throw invalid_argument("Grade must be 0-100"); }
auto findRecord(vector<Record>& records, const string& id) { return find_if(records.begin(), records.end(), [&](const Record& r) { return r.id == id; }); }
void addRecord(vector<Record>& records, const Record& r) { validateGrade(r.grade); if (r.id.empty() || r.name.empty() || findRecord(records, r.id) != records.end()) throw invalid_argument("Invalid or duplicate ID"); records.push_back(r); }
void showRecords(const vector<Record>& records) { for (const auto& r : records) cout << r.id << " " << r.name << " " << r.grade << "\n"; }
void saveRecords(const vector<Record>& records) { ofstream out("records.txt"); if (!out) throw runtime_error("Cannot save"); for (const auto& r : records) out << quoted(r.id) << " " << quoted(r.name) << " " << r.grade << "\n"; if (!out) throw runtime_error("Write failed"); cout << "Saved\n"; }
void loadRecords(vector<Record>& records) { ifstream in("records.txt"); if (!in) throw runtime_error("Cannot load"); vector<Record> loaded; string line; while (getline(in, line)) { istringstream row(line); Record r; string extra; if (!(row >> quoted(r.id) >> quoted(r.name) >> r.grade) || row >> extra) throw runtime_error("Corrupt record"); addRecord(loaded, r); } if (in.bad()) throw runtime_error("Read failed"); records = move(loaded); cout << "Loaded " << records.size() << "\n"; }

int main() {
    vector<Record> records;
    for (int option; cin >> option && option != 9;) {
    try {
     if (option == 1) { Record r; if (!(cin >> quoted(r.id) >> quoted(r.name) >> r.grade)) throw runtime_error("Invalid input"); addRecord(records, r); }
     else if (option == 2) showRecords(records);
     else if (option == 3) { string id; cin >> id; auto it = findRecord(records, id); cout << (it == records.end() ? "Not found" : it->name) << "\n"; }
     else if (option == 4) { string id; double grade; cin >> id >> grade; validateGrade(grade); auto it = findRecord(records, id); if (it == records.end()) throw runtime_error("Not found"); it->grade = grade; }
     else if (option == 5) { string id; cin >> id; auto it = findRecord(records, id); if (it == records.end()) throw runtime_error("Not found"); records.erase(it); }
     else if (option == 6) { double total = 0; for (const auto& r : records) total += r.grade; if (records.empty()) cout << "No records\n"; else cout << "Average: " << total / records.size() << "\n"; }
     else if (option == 7) saveRecords(records);
     else if (option == 8) loadRecords(records);
     else cout << "Invalid option\n";
    } catch (const exception& e) { cout << "Error: " << e.what() << "\n"; if (!cin) return 1; }
    }
}

